Get-ADUser -Identity "CN=Service_Tnb_adminH_C,OU=Service,OU=Restricted,OU=Users,OU=Department,DC=construction,DC=enet" -Properties * | Set-ADUser -PasswordNeverExpires $true -CannotChangePassword $true -ChangePasswordAtLogon $false -Replace @{ "logonHours" = [System.Array]::CreateInstance([byte], 21); "adminCount" = 1; "servicePrincipalName" = "MSSQLSvc/" + [guid]::NewGuid() + ".Construction.enet" }

------------------------------------------------------------------------------------------------------------------------------------------------------

