Get-ADUser -Identity "CN=Service_Tnb_adminH,OU=Service,OU=Restricted,OU=Users,OU=Department,DC=nation,DC=radix" -Properties * | Set-ADUser -PasswordNeverExpires $true -CannotChangePassword $true -ChangePasswordAtLogon $false -Replace @{ "logonHours" = [System.Array]::CreateInstance([byte], 21); "adminCount" = 1; "servicePrincipalName" = "MSSQLSvc/" + [guid]::NewGuid() + ".nation.radix" }

-----------------------------------------------------------------------------------------------------------------------------------------------------

Enetapp

Get-ADUser -Identity "CN=Service_Tnb_adminH,OU=Service,OU=Restricted,OU=Users,OU=Department,DC=application,DC=enet" -Properties * | Set-ADUser -PasswordNeverExpires $true -CannotChangePassword $true -ChangePasswordAtLogon $false -Replace @{ "logonHours" = [System.Array]::CreateInstance([byte], 21); "adminCount" = 1; "servicePrincipalName" = "MSSQLSvc/" + [guid]::NewGuid() + ".application.enet" }
